toolArgs.file_text:
@page "/settings"
@namespace sv_ece5e5c42e5841cbbf760336ec10c78f.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="section => _activeSection = section" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";
}

arguments.file_text:
.settings-dashboard {
    display: flex;
    min-height: 600px;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    background: #fff;
}

/* Sidebar */
::deep .settings-sidebar {
    display: flex;
    flex-direction: column;
    width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1rem 0;
}

::deep .sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    border: none;
    background: transparent;
    cursor: pointer;
    font-size: 0.95rem;
    color: #555;
    text-align: left;
    transition: background 0.15s, color 0.15s;
}

::deep .sidebar-item:hover {
    background: #e9ecef;
    color: #333;
}

::deep .sidebar-item.active {
    background: #0d6efd;
    color: #fff;
    font-weight: 600;
}

/* Main content area */
.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

/* Shared section styles */
::deep .settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #333;
}

::deep .settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
    color: #444;
}

::deep .form-group {
    margin-bottom: 1rem;
}

::deep .form-group label,
::deep .form-group legend {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 600;
    font-size: 0.9rem;
    color: #555;
}

::deep .form-group input[type="text"],
::deep .form-group input[type="email"],
::deep .form-group input[type="password"],
::deep .form-group textarea,
::deep .form-group select {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 0.95rem;
}

::deep .form-group textarea {
    resize: vertical;
}

::deep .form-actions {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

::deep .btn-primary {
    padding: 0.5rem 1.25rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

::deep .btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

::deep .btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

::deep .btn-secondary {
    padding: 0.5rem 1.25rem;
    background: #6c757d;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

::deep .btn-secondary:hover:not(:disabled) {
    background: #5a6268;
}

::deep .btn-danger {
    padding: 0.4rem 0.9rem;
    background: #dc3545;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
}

::deep .btn-danger:hover:not(:disabled) {
    background: #c82333;
}

::deep .btn-sm {
    padding: 0.25rem 0.6rem;
    font-size: 0.8rem;
}

/* Toast messages */
::deep .toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

::deep .toast.success {
    background: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
}

::deep .toast.error {
    background: #f8d7da;
    color: #721c24;
    border: 1px solid #f5c6cb;
}

/* Toggle labels */
::deep .toggle-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    margin-bottom: 0.5rem;
}

::deep .toggle-group {
    margin-bottom: 1.5rem;
}

/* Avatar */
::deep .avatar-preview {
    margin-bottom: 1.5rem;
}

::deep .avatar-image {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #dee2e6;
}

::deep .avatar-url-display {
    font-size: 0.8rem;
    color: #888;
    margin-top: 0.25rem;
    word-break: break-all;
}

/* Channel list */
::deep .channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

::deep .channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

/* Expandable panel */
::deep .expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 6px;
    margin-bottom: 1.5rem;
}

::deep .panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 600;
}

::deep .panel-content {
    padding: 1rem;
    border-top: 1px solid #dee2e6;
}

/* Two-factor section */
::deep .twofa-section {
    margin-bottom: 1.5rem;
}

::deep .twofa-status {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

::deep .status-indicator {
    font-weight: 600;
    font-size: 0.9rem;
}

::deep .status-indicator.enabled {
    color: #28a745;
}

::deep .status-indicator.disabled {
    color: #dc3545;
}

::deep .info-text {
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.5rem;
}

::deep .current-session-badge {
    font-size: 0.8rem;
    background: #e9ecef;
    padding: 0.2rem 0.5rem;
    border-radius: 3px;
    color: #555;
}

/* Sessions table */
::deep .sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.5rem;
}

::deep .sessions-table th,
::deep .sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #dee2e6;
}

::deep .sessions-table th {
    background: #f8f9fa;
    font-size: 0.85rem;
    font-weight: 600;
    color: #555;
}

/* Dialog overlay */
::deep .dialog-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

::deep .dialog {
    background: #fff;
    padding: 1.5rem;
    border-radius: 8px;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

::deep .dialog h4 {
    margin-top: 0;
    margin-bottom: 0.75rem;
}

::deep .dialog-actions {
    margin-top: 1.25rem;
    display: flex;
    gap: 0.75rem;
}

/* Radio groups */
::deep .radio-group {
    display: flex;
    gap: 1.5rem;
}

::deep .radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

/* Appearance preview */
::deep .preview-area {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    transition: all 0.2s;
}

::deep .preview-area.theme-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

::deep .preview-area.theme-light {
    background: #ffffff;
    color: #333;
}

::deep .preview-area.theme-system {
    background: #f8f9fa;
    color: #333;
}

::deep .preview-area.font-small {
    font-size: 0.8rem;
}

::deep .preview-area.font-medium {
    font-size: 1rem;
}

::deep .preview-area.font-large {
    font-size: 1.2rem;
}

::deep .preview-area.compact {
    padding: 0.75rem;
    line-height: 1.2;
}

::deep .preview-card {
    margin-top: 0.75rem;
    padding: 0.75rem;
    border: 1px solid currentColor;
    border-radius: 4px;
    opacity: 0.8;
}

::deep .preview-button {
    margin-top: 0.5rem;
    padding: 0.3rem 0.75rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    font-size: inherit;
}

::deep .loading {
    color: #6c757d;
    font-style: italic;
}

::deep .empty-state {
    color: #888;
    font-style: italic;
}

::deep fieldset {
    border: none;
    padding: 0;
    margin: 0 0 1rem 0;
}

