+    margin-top: 1.25rem;
+    display: flex;
+    gap: 0.75rem;
+}
+
+/* Radio groups */
+::deep .radio-group {
+    display: flex;
+    gap: 1.5rem;
+}
+
+::deep .radio-label {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+}
+
+/* Appearance preview */
+::deep .preview-area {
+    margin-top: 1.5rem;
+    padding: 1.5rem;
+    border: 1px solid #dee2e6;
+    border-radius: 8px;
+    transition: all 0.2s;
+}
+
+::deep .preview-area.theme-dark {
+    background: #1e1e2e;
+    color: #cdd6f4;
+    border-color: #45475a;
+}
+
+::deep .preview-area.theme-light {
+    background: #ffffff;
+    color: #333;
+}
+
+::deep .preview-area.theme-system {
+    background: #f8f9fa;
+    color: #333;
+}
+
+::deep .preview-area.font-small {
+    font-size: 0.8rem;
+}
+
+::deep .preview-area.font-medium {
+    font-size: 1rem;
+}
+
+::deep .preview-area.font-large {
+    font-size: 1.2rem;
+}
+
+::deep .preview-area.compact {
+    padding: 0.75rem;
+    line-height: 1.2;
+}
+
+::deep .preview-card {
+    margin-top: 0.75rem;
+    padding: 0.75rem;
+    border: 1px solid currentColor;
+    border-radius: 4px;
+    opacity: 0.8;
+}
+
+::deep .preview-button {
+    margin-top: 0.5rem;
+    padding: 0.3rem 0.75rem;
+    background: #0d6efd;
+    color: #fff;
+    border: none;
+    border-radius: 4px;
+    font-size: inherit;
+}
+
+::deep .loading {
+    color: #6c757d;
+    font-style: italic;
+}
+
+::deep .empty-state {
+    color: #888;
+    font-style: italic;
+}
+
+::deep fieldset {
+    border: none;
+    padding: 0;
+    margin: 0 0 1rem 0;
+}
+
